From dad84e9dd4ab3ab074e6817acb5e09ac2804f030 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:30:58 +0100
Subject: [PATCH] faces: add an option to show sensors in warning colors above
 a threshold

System Monitor widgets always draw a sensor in its own color, so there is
no way to notice at a glance that memory or a CPU core is nearly full. Add
warning and critical thresholds to the appearance settings, off by default.

BUG: 495130
---
 faces/ConfigAppearance.qml     | 43 ++++++++++++++++++++++++++++++++++
 faces/SensorFaceController.cpp | 36 ++++++++++++++++++++++++++++
 faces/SensorFaceController.h   | 18 ++++++++++++++
 faces/import/SensorFace.qml    | 38 +++++++++++++++++++++++++++++-
 4 files changed, 134 insertions(+), 1 deletion(-)

diff --git a/faces/ConfigAppearance.qml b/faces/ConfigAppearance.qml
index f32840db..a3edab74 100644
--- a/faces/ConfigAppearance.qml
+++ b/faces/ConfigAppearance.qml
@@ -29,6 +29,8 @@ Kirigami.FormLayout {
         controller.faceId = cfg_chartFace;
         controller.showTitle = cfg_showTitle
         controller.updateRateLimit = cfg_updateRateLimit
+        controller.warningThreshold = cfg_warningThreshold
+        controller.criticalThreshold = cfg_criticalThreshold

         var preset = pendingPreset;
         pendingPreset = "";
@@ -43,11 +45,15 @@ Kirigami.FormLayout {
     property alias cfg_showTitle: showTitleCheckbox.checked
     property string cfg_chartFace
     property alias cfg_updateRateLimit: updateRateLimitSpinBox.value
+    property alias cfg_warningThreshold: warningThresholdSpinBox.value
+    property alias cfg_criticalThreshold: criticalThresholdSpinBox.value

     onCfg_titleChanged: configurationChanged();
     onCfg_showTitleChanged: configurationChanged()
     onCfg_chartFaceChanged: configurationChanged();
     onCfg_updateRateLimitChanged: configurationChanged();
+    onCfg_warningThresholdChanged: configurationChanged();
+    onCfg_criticalThresholdChanged: configurationChanged();

     // config keys of the selected preset to be applied on save
     property string pendingPreset
@@ -57,6 +63,8 @@ Kirigami.FormLayout {
         cfg_chartFace = controller.faceId;
         cfg_showTitle = controller.showTitle
         cfg_updateRateLimit = controller.updateRateLimit
+        cfg_warningThreshold = controller.warningThreshold
+        cfg_criticalThreshold = controller.criticalThreshold
     }

     Charts.ColorGradientSource {
@@ -225,4 +233,39 @@ Kirigami.FormLayout {
             }
         }
     }
+
+    Faces.SuffixSpinBox {
+        id: warningThresholdSpinBox
+        Layout.preferredWidth: titleField.implicitWidth
+
+        Kirigami.FormData.label: i18nd("KSysGuardSensorFaces", "Use Warning Color Above:")
+
+        to: 100
+        stepSize: 5
+        spacing: 0
+        suffix: value > 0 ? i18ndc("KSysGuardSensorFaces", "Percent suffix", "%") : ""
+
+        textFromValue: function(value, locale) {
+            return value > 0 ? value.toString() : i18nd("KSysGuardSensorFaces", "Never");
+        }
+        valueFromText: function(text, locale) {
+            var v = parseInt(text);
+            return isNaN(v) ? 0 : v;
+        }
+    }
+
+    Faces.SuffixSpinBox {
+        id: criticalThresholdSpinBox
+        Layout.preferredWidth: titleField.implicitWidth
+
+        Kirigami.FormData.label: i18nd("KSysGuardSensorFaces", "Use Critical Color Above:")
+
+        to: 100
+        stepSize: 5
+        spacing: 0
+        suffix: value > 0 ? i18ndc("KSysGuardSensorFaces", "Percent suffix", "%") : ""
+
+        textFromValue: warningThresholdSpinBox.textFromValue
+        valueFromText: warningThresholdSpinBox.valueFromText
+    }
 }
diff --git a/faces/SensorFaceController.cpp b/faces/SensorFaceController.cpp
index 89fbf8c4..5b221663 100644
--- a/faces/SensorFaceController.cpp
+++ b/faces/SensorFaceController.cpp
@@ -664,6 +664,40 @@ void SensorFaceController::setUpdateRateLimit(int limit)
     Q_EMIT updateRateLimitChanged();
 }

+int SensorFaceController::warningThreshold() const
+{
+    return d->appearanceGroup.readEntry<int>(QStringLiteral("warningThreshold"), 0);
+}
+
+void SensorFaceController::setWarningThreshold(int threshold)
+{
+    if (threshold == warningThreshold()) {
+        return;
+    }
+
+    d->appearanceGroup.writeEntry("warningThreshold", threshold);
+    d->syncTimer->start();
+
+    Q_EMIT warningThresholdChanged();
+}
+
+int SensorFaceController::criticalThreshold() const
+{
+    return d->appearanceGroup.readEntry<int>(QStringLiteral("criticalThreshold"), 0);
+}
+
+void SensorFaceController::setCriticalThreshold(int threshold)
+{
+    if (threshold == criticalThreshold()) {
+        return;
+    }
+
+    d->appearanceGroup.writeEntry("criticalThreshold", threshold);
+    d->syncTimer->start();
+
+    Q_EMIT criticalThresholdChanged();
+}
+
 // from face config, immutable by the user
 QString SensorFaceController::name() const
 {
@@ -908,6 +942,8 @@ void SensorFaceController::reloadConfig()
     Q_EMIT sensorLabelsChanged();
     Q_EMIT showTitleChanged();
     Q_EMIT updateRateLimitChanged();
+    Q_EMIT warningThresholdChanged();
+    Q_EMIT criticalThresholdChanged();
 }

 void SensorFaceController::loadPreset(const QString &preset)
diff --git a/faces/SensorFaceController.h b/faces/SensorFaceController.h
index 5c2f1bd5..63ce455d 100644
--- a/faces/SensorFaceController.h
+++ b/faces/SensorFaceController.h
@@ -160,6 +160,16 @@ class SENSORFACES_EXPORT SensorFaceController : public QObject
      * The minimum time that needs to elapse, in milliseconds, between updates of the face.
      */
     Q_PROPERTY(int updateRateLimit READ updateRateLimit WRITE setUpdateRateLimit NOTIFY updateRateLimitChanged)
+    /**
+     * The percentage of a sensor's range above which the face shows that sensor
+     * in the warning color. 0 disables it.
+     */
+    Q_PROPERTY(int warningThreshold READ warningThreshold WRITE setWarningThreshold NOTIFY warningThresholdChanged)
+    /**
+     * The percentage of a sensor's range above which the face shows that sensor
+     * in the critical color. 0 disables it.
+     */
+    Q_PROPERTY(int criticalThreshold READ criticalThreshold WRITE setCriticalThreshold NOTIFY criticalThresholdChanged)
     /**
      * Contains the paths of missing sensors, if there are any.
      */
@@ -225,6 +235,12 @@ public:
     int updateRateLimit() const;
     void setUpdateRateLimit(int limit);

+    int warningThreshold() const;
+    void setWarningThreshold(int threshold);
+
+    int criticalThreshold() const;
+    void setCriticalThreshold(int threshold);
+
     // from face config, immutable by the user
     QString name() const;
     const QString icon() const;
@@ -308,6 +324,8 @@ Q_SIGNALS:
     void sensorColorsChanged();
     void sensorLabelsChanged();
     void updateRateLimitChanged();
+    void warningThresholdChanged();
+    void criticalThresholdChanged();
     void faceConfigurationChanged();
     void missingSensorsChanged();

diff --git a/faces/import/SensorFace.qml b/faces/import/SensorFace.qml
index 6cdb7713..9f8af3aa 100644
--- a/faces/import/SensorFace.qml
+++ b/faces/import/SensorFace.qml
@@ -36,7 +36,43 @@ Faces.AbstractSensorFace {
         source: Charts.ArraySource {
             array: root.controller.highPrioritySensorIds
         }
-        map: root.controller.sensorColors
+        map: {
+            const colors = root.controller.sensorColors;
+            if (!thresholdSensors.enabled || thresholdSensors.count === 0) {
+                return colors;
+            }
+            const result = Object.assign({}, colors);
+            for (let i = 0; i < thresholdSensors.count; ++i) {
+                const sensor = thresholdSensors.objectAt(i);
+                if (sensor && sensor.thresholdColor) {
+                    result[sensor.sensorId] = sensor.thresholdColor;
+                }
+            }
+            return result;
+        }
+    }
+    Instantiator {
+        id: thresholdSensors
+
+        readonly property bool enabled: root.controller.warningThreshold > 0 || root.controller.criticalThreshold > 0
+
+        model: enabled ? root.controller.highPrioritySensorIds : []
+        delegate: Sensors.Sensor {
+            required property string modelData
+            sensorId: modelData
+            updateRateLimit: root.controller.updateRateLimit
+
+            readonly property real percentage: maximum > minimum ? (value - minimum) / (maximum - minimum) * 100 : NaN
+            readonly property var thresholdColor: {
+                if (root.controller.criticalThreshold > 0 && percentage >= root.controller.criticalThreshold) {
+                    return Kirigami.Theme.negativeTextColor;
+                }
+                if (root.controller.warningThreshold > 0 && percentage >= root.controller.warningThreshold) {
+                    return Kirigami.Theme.neutralTextColor;
+                }
+                return undefined;
+            }
+        }
     }
     Charts.ColorGradientSource {
         baseColor: Kirigami.Theme.highlightColor
-- 
